#!/usr/bin/env python3
"""
Build one text-layer fixture per document type, for all 58 types.

PURPOSE. The classifier carries 58 profiles but only five had ever been run
against a document of their own type. The other 53 were written from the statutory
forms and were plausible-but-unverified. This generator closes that gap: every
profile now has at least one document to classify, and `classify.test.ts` asserts
each one lands on its own code and reports a full confusion matrix.

FIDELITY. Each fixture reproduces the distinguishing STRUCTURE of its form — the
statutory citation, the party designations, the operative phrasing, the field
labels a registry actually prints. Generic filler would make the test worthless:
the whole point is to exercise the cues and, more importantly, the ANTI-cues that
separate near neighbours (plaint vs written statement, FIR vs charge sheet, order
vs judgement, sale deed vs agreement to sell, notice vs complaint).

All names, numbers, addresses and facts are fictional. The forms are faithful.
"""

import os, sys
from reportlab.lib.pagesizes import A4
from reportlab.pdfgen import canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

HERE = os.path.dirname(os.path.abspath(__file__))
W, H = A4

DEVA = "/usr/share/fonts/truetype/lohit-devanagari/Lohit-Devanagari.ttf"
HAS_DEVA = os.path.exists(DEVA)
if HAS_DEVA:
    pdfmetrics.registerFont(TTFont("Ind-deva", DEVA))

B = "Helvetica-Bold"          # bold
C = "CENTRE"                  # marker for a centred line
DV = "DEVA"                   # marker for a Devanagari line
M = "MONO"                    # marker for a monospaced (column-aligned) line

# Bank statements, cause lists and invoice line-item grids are column-aligned in
# real life — set in a monospaced face or laid out on tab stops. Rendering them
# in a proportional face with hand-counted spaces produces columns that LOOK
# aligned in the source and are not aligned on the page, which makes them a
# dishonest test of column detection.


def build(code, lines):
    """Render a list of lines. A line may be a str, or (str, flag)."""
    path = os.path.join(HERE, f"type_{code}.pdf")
    c = canvas.Canvas(path, pagesize=A4)
    y = H - 58
    for item in lines:
        if item is None:
            y -= 13
            continue
        text, flag = (item if isinstance(item, tuple) else (item, None))
        font, size, centre = "Helvetica", 10, False
        if flag == B:
            font = B
        elif flag == C:
            font, size, centre = B, 11.5, True
        elif flag == DV:
            if not HAS_DEVA:
                continue
            font = "Ind-deva"
        elif flag == M:
            font, size = "Courier", 8.5
        c.setFont(font, size)
        if centre:
            c.drawCentredString(W / 2, y, text)
        else:
            c.drawString(54, y, text)
        y -= 13.5
        if y < 58:
            c.showPage()
            y = H - 58
    c.save()
    return path


